body:
/* ── gitcorpus — evidence ledger ──────────────────────────────────
   Bone paper ground, iron-black ink, archival navy actions, vermilion
   reserved for provenance/incomplete. Unified tables, card filters with air.
   ──────────────────────────────────────────────────────────────── */

:root {
  color-scheme: light;
  --gc-bg: #f7f4ec;
  --gc-surface: #fffdf8;
  --gc-surface-alt: #efe9d9;
  --gc-surface-hover: #e7e0cc;
  --gc-border: #e2dbc6;
  --gc-border-strong: #c4ba9f;
  --gc-text: #201d16;
  --gc-heading: #15130d;
  --gc-muted: #6d6554;
  --gc-gutter: #b8b09b;
  --gc-accent: #1d3557;
  --gc-accent-hover: #16294a;
  --gc-accent-text: #ffffff;
  --gc-accent-soft: #e2e8f0;
  --gc-ok: #1e6b3a;
  --gc-ok-bg: #e2f0e5;
  --gc-down: #b3261e;
  --gc-down-bg: #fbe9e7;
  --gc-warn: #7a5200;
  --gc-warn-bg: #f5ead0;
  --gc-run: #1d3557;
  --gc-run-bg: #e2e8f0;
  --gc-mono: "Cascadia Code", "JetBrains Mono", ui-monospace, SFMono-Regular, Consolas, monospace;
  --gc-radius: 6px;
  --gc-shadow: 0 1px 2px rgba(20, 24, 28, 0.06);
  --gc-shadow-modal: 0 8px 28px rgba(20, 24, 28, 0.16);
}

:root,
[data-theme="dark"] {
  --gc-selected: rgba(217, 180, 90, 0.16);
}

[data-theme="dark"] {
  color-scheme: dark;
  --gc-bg: #0b0d10;
  --gc-surface: #101318;
  --gc-surface-alt: #151a20;
  --gc-surface-hover: #1a2027;
  --gc-border: #1c2127;
  --gc-border-strong: #2c3540;
  --gc-text: #a9b0b7;
  --gc-heading: #d6d9dc;
  --gc-muted: #79828e;
  --gc-gutter: #4d5866;
  --gc-accent: #a38b52;
  --gc-accent-hover: #bfa468;
  --gc-accent-text: #0b0d10;
  --gc-accent-soft: rgba(163, 139, 82, 0.14);
  --gc-ok: #7fa588;
  --gc-ok-bg: rgba(127, 165, 136, 0.12);
  --gc-down: #c08279;
  --gc-down-bg: rgba(192, 130, 121, 0.12);
  --gc-warn: #b3995e;
  --gc-warn-bg: rgba(179, 153, 94, 0.12);
  --gc-run: #a38b52;
  --gc-run-bg: rgba(163, 139, 82, 0.12);
  --gc-selected: rgba(163, 139, 82, 0.16);
  --gc-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
  --gc-shadow-modal: 0 12px 28px rgba(0, 0, 0, 0.7);
}

/* prefers-color-scheme fallback (no explicit choice stored) */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --gc-bg: #0b0d10;
    --gc-surface: #101318;
    --gc-surface-alt: #151a20;
    --gc-surface-hover: #1a2027;
    --gc-border: #1c2127;
    --gc-border-strong: #2c3540;
    --gc-text: #a9b0b7;
    --gc-heading: #d6d9dc;
    --gc-muted: #79828e;
    --gc-gutter: #4d5866;
    --gc-accent: #a38b52;
    --gc-accent-hover: #bfa468;
    --gc-accent-text: #0b0d10;
    --gc-accent-soft: rgba(163, 139, 82, 0.14);
    --gc-ok: #7fa588;
    --gc-ok-bg: rgba(127, 165, 136, 0.12);
    --gc-down: #c08279;
    --gc-down-bg: rgba(192, 130, 121, 0.12);
    --gc-warn: #b3995e;
    --gc-warn-bg: rgba(179, 153, 94, 0.12);
    --gc-run: #a38b52;
    --gc-run-bg: rgba(163, 139, 82, 0.12);
    --gc-selected: rgba(163, 139, 82, 0.16);
    --gc-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
    --gc-shadow-modal: 0 12px 28px rgba(0, 0, 0, 0.7);
  }
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--gc-bg);
  color: var(--gc-text);
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, sans-serif;
  font-size: 15px;
  line-height: 1.55;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

a {
  color: var(--gc-accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

:focus-visible {
  outline: 2px solid var(--gc-accent);
  outline-offset: 2px;
}

::selection {
  background: var(--gc-accent);
  color: var(--gc-accent-text);
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--gc-surface);
  padding: 0.5rem 0.75rem;
  z-index: 20;
}

.skip-link:focus {
  left: 0.5rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ─────────────────────────────────────────────────────── */

.site-header {
  display: flex;
  align-items: center;
  gap: 0.75rem 1rem;
  padding: 0 1.25rem;
  min-height: 3.25rem;
  background: var(--gc-surface);
  border-bottom: 1px solid var(--gc-border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.brand {
  flex: none;
  line-height: 1;
  font-weight: 650;
  font-size: 0.95rem;
  letter-spacing: 0.01em;
  color: var(--gc-heading);
  font-family: var(--gc-mono);
}

.brand::after {
  content: "";
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-left: 0.45rem;
  background: var(--gc-accent);
  border-radius: 1px;
}

.brand:hover {
  text-decoration: none;
}

.site-nav {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.15rem;
  margin-right: auto;
  min-width: 0;
}

.site-nav a,
.site-nav .nav-soon {
  font: inherit;
  font-size: 0.92rem;
  font-weight: 450;
  line-height: 1;
  padding: 0.42rem 0.75rem;
  border-radius: 5px;
}

.site-nav a {
  color: var(--gc-muted);
}

.site-nav a:hover {
  background: var(--gc-surface-alt);
  color: var(--gc-heading);
  text-decoration: none;
}

.site-nav a[aria-current="page"] {
  color: var(--gc-heading);
  background: var(--gc-surface-alt);
  font-weight: 600;
}

.site-nav a[aria-current="page"]:hover {
  background: var(--gc-surface-hover);
}

.site-nav .nav-soon {
  margin-left: 0.75rem;
  color: var(--gc-muted);
  cursor: not-allowed;
  user-select: none;
  -webkit-user-select: none;
  opacity: 0.5;
}

.site-nav .nav-soon:hover {
  cursor: not-allowed;
}

.status-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2rem;
  min-height: 2rem;
  padding: 0.3rem;
  border-radius: 4px;
  flex: none;
}

.site-header .button.ghost {
  flex: none;
  min-height: 2rem;
  padding: 0.35rem 0.7rem;
  line-height: 1.2;
  font-family: var(--gc-mono);
  font-size: 0.7rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.site-header kbd {
  flex: none;
  cursor: help;
}

.status-link:hover {
  background: var(--gc-surface-alt);
  text-decoration: none;
}

.status-link:hover .dot,
.status-link:hover > span {
  filter: brightness(1.15);
}

/* ── Content column ─────────────────────────────────────────────── */

.content {
  width: 100%;
  max-width: 1160px;
  margin: 0 auto;
  padding: 1.5rem 1.5rem 5rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

/* ── Panels & cards ─────────────────────────────────────────────── */

.panel {
  position: relative;
  background: var(--gc-surface);
  border: 1px solid var(--gc-border);
  border-radius: 8px;
  padding: 1.25rem 1.5rem 1.35rem;
  box-shadow: var(--gc-shadow);
}

.panel::before {
  content: "";
  display: block;
  height: 3px;
  background: var(--gc-accent);
  border-radius: 8px 8px 0 0;
  margin: -1.25rem -1.5rem 1.1rem;
}

.panel::after {
  content: "";
  position: absolute;
  right: 9px;
  bottom: 9px;
  width: 8px;
  height: 8px;
  border-right: 1px solid var(--gc-border-strong);
  border-bottom: 1px solid var(--gc-border-strong);
  opacity: 0.55;
  pointer-events: none;
}

[data-theme="dark"] .panel::before {
  background: var(--gc-border-strong);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .panel::before {
    background: var(--gc-border-strong);
  }
}

.panel > .panel-head:first-child {
  margin-top: 0;
}

.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  margin-bottom: 0.9rem;
}

.panel-head h1,
.panel-head h2,
#run-status > h2,
#quality-panel > h2 {
  margin: 0;
  font-weight: 650;
  color: var(--gc-heading);
  letter-spacing: 0.01em;
  line-height: 1.2;
}

.panel-head h1 {
  font-size: 1.6rem;
}

.panel-head h2 {
  font-size: 1.25rem;
}

#run-status > h2,
#quality-panel > h2 {
  font-size: 1.25rem;
}

.provenance {
  margin: -0.15rem 0 0.9rem;
  color: var(--gc-muted);
  font-size: 0.82rem;
}

#run-status > h2 {
  margin: 0.9rem 0 0.5rem;
}

#quality-panel > h2 {
  margin: 0 0 0.7rem;
}

.panel-head p {
  margin: 0;
  font-size: 0.85rem;
}

/* micro-label pattern */
.field-label,
.data-table thead th,
.diff-label,
.panel .eyebrow {
  font-size: 0.7rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-family: var(--gc-mono);
}

.health-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 0.9rem;
}

.card {
  background: var(--gc-surface-alt);
  border: 1px solid var(--gc-border);
  border-radius: 6px;
  padding: 0.8rem 1rem;
}

.health-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  background: var(--gc-surface);
}

.health-label {
  font-family: var(--gc-mono);
  font-size: 0.7rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gc-muted);
}

/* severity cards (metrics) */
.card.ok {
  border-color: color-mix(in srgb, var(--gc-ok) 35%, var(--gc-border));
}

.card.warn,
.card.fail {
  border-color: color-mix(in srgb, var(--gc-down) 35%, var(--gc-border));
}

.card.na {
  opacity: 0.75;
}

/* ── Pills & badges ─────────────────────────────────────────────── */

.badge,
.pill {
  display: inline-block;
  padding: 0.18rem 0.6rem;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  line-height: 1.5;
  vertical-align: middle;
  border: 1px solid var(--gc-border-strong);
  background: transparent;
  color: var(--gc-muted);
  font-family: var(--gc-mono);
}

.badge.ok,
.pill.done {
  color: var(--gc-ok);
  border-color: var(--gc-ok);
  background: color-mix(in srgb, var(--gc-ok) 8%, transparent);
}

.badge.down,
.badge.fail,
.pill.failed {
  color: var(--gc-down);
  border-color: var(--gc-down);
  background: color-mix(in srgb, var(--gc-down) 8%, transparent);
}

.badge.warn,
.pill.partial {
  color: var(--gc-warn);
  border-color: var(--gc-warn);
  background: color-mix(in srgb, var(--gc-warn) 8%, transparent);
}

.badge.na,
.pill.queued {
  color: var(--gc-muted);
  border-color: var(--gc-border-strong);
  background: transparent;
}

.pill.running {
  color: var(--gc-accent);
  border-color: var(--gc-accent);
  background: color-mix(in srgb, var(--gc-accent) 8%, transparent);
}

.pill.cancelled {
  color: var(--gc-muted);
  border-color: var(--gc-border-strong);
  background: transparent;
}

.badge.incomplete {
  color: var(--gc-down);
  border-color: var(--gc-down);
  background: transparent;
}

.badge.archived {
  color: var(--gc-muted);
  border-color: var(--gc-border-strong);
  background: transparent;
}

/* ── Forms ──────────────────────────────────────────────────────── */

input,
select,
textarea {
  background: var(--gc-surface);
  color: var(--gc-text);
  border: 1px solid var(--gc-border-strong);
  border-radius: 4px;
  padding: 0.42rem 0.6rem;
  font: inherit;
  font-size: 0.9rem;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

input:hover:not([disabled]):not([readonly]),
select:hover:not([disabled]):not([readonly]) {
  border-color: color-mix(in srgb, var(--gc-accent) 45%, var(--gc-border-strong));
}

input:focus,
select:focus,
textarea:focus {
  outline: none;
  border-color: var(--gc-accent);
  box-shadow: 0 0 0 3px var(--gc-accent-soft);
}

input:focus-visible {
  outline: none;
}

input[disabled],
input[readonly],
select[disabled] {
  color: var(--gc-muted);
  background: var(--gc-surface-alt);
  border-color: var(--gc-border);
  cursor: not-allowed;
}

input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--gc-accent);
  width: 0.95rem;
  height: 0.95rem;
}

input[type="file"] {
  padding: 0.3rem 0.4rem;
  color: var(--gc-muted);
}

input[type="file"]::-webkit-file-upload-button {
  font: inherit;
  font-size: 0.86rem;
  font-weight: 550;
  padding: 0.32rem 0.7rem;
  margin-right: 0.6rem;
  border: 1px solid var(--gc-border-strong);
  border-radius: 4px;
  background: var(--gc-surface-alt);
  color: var(--gc-heading);
  cursor: pointer;
}

input[type="file"]::file-selector-button {
  font: inherit;
  font-size: 0.86rem;
  font-weight: 550;
  padding: 0.32rem 0.7rem;
  margin-right: 0.6rem;
  border: 1px solid var(--gc-border-strong);
  border-radius: 4px;
  background: var(--gc-surface-alt);
  color: var(--gc-heading);
  cursor: pointer;
}

input[type="file"]:hover::-webkit-file-upload-button {
  background: var(--gc-surface-hover);
}

input[type="file"]:hover::file-selector-button {
  background: var(--gc-surface-hover);
}

::placeholder {
  color: var(--gc-muted);
  font-family: var(--gc-mono);
  font-size: 0.86em;
}

/* ── Buttons ────────────────────────────────────────────────────── */

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  padding: 0.4rem 0.85rem;
  border-radius: 4px;
  border: 1px solid var(--gc-border-strong);
  background: var(--gc-surface);
  color: var(--gc-heading);
  font: inherit;
  font-size: 0.86rem;
  font-weight: 550;
  cursor: pointer;
  transition: background 100ms ease, border-color 100ms ease, color 100ms ease;
}

.button:hover {
  background: var(--gc-surface-alt);
  text-decoration: none;
}

.button:active {
  transform: translateY(0.5px);
}

.button:disabled,
.button[disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}

.button.primary {
  background: var(--gc-accent);
  border-color: var(--gc-accent);
  color: var(--gc-accent-text);
}

.button.primary:hover {
  background: var(--gc-accent-hover);
  border-color: var(--gc-accent-hover);
}

.button.ghost {
  background: transparent;
  border-color: var(--gc-border);
  color: var(--gc-muted);
}

.button.ghost:hover {
  color: var(--gc-heading);
  border-color: var(--gc-border-strong);
  background: var(--gc-surface-alt);
}

.button.danger {
  background: transparent;
  border-color: color-mix(in srgb, var(--gc-down) 55%, var(--gc-border));
  color: var(--gc-down);
}

.button.danger:hover {
  background: var(--gc-down-bg);
}

/* ── Tables ─────────────────────────────────────────────────────── */

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--gc-border);
  border-radius: 6px;
  background: var(--gc-surface);
  scrollbar-width: thin;
  scrollbar-color: var(--gc-border-strong) transparent;
}

.table-scroll {
  max-height: 70vh;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--gc-border-strong) transparent;
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
}

.sticky-head thead th {
  position: sticky;
  top: 0;
  background: var(--gc-surface-alt);
  z-index: 2;
}

/* back-compat with the id-bound rules this pass replaces */
#run-table .table-wrap {
  max-height: 70vh;
  overflow-y: auto;
  border: 1px solid var(--gc-border);
  border-radius: 6px;
}

#run-table thead th {
  position: sticky;
  top: 0;
  background: var(--gc-surface-alt);
  z-index: 2;
}

#run-table-count {
  margin: 0 0 0.5rem;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

.data-table th,
.data-table td {
  text-align: left;
  padding: 0.6rem 0.75rem;
  border-bottom: 1px solid var(--gc-border);
  white-space: nowrap;
  vertical-align: top;
}

.data-table thead th {
  color: var(--gc-muted);
  font-size: 0.68rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-bottom: 1px solid var(--gc-border-strong);
  background: var(--gc-surface-alt);
}

.data-table th.num {
  text-align: right;
}

.data-table th.col-actions {
  text-align: right;
}

.data-table th.col-gutter {
  width: 2.5rem;
}

.data-table td.gutter {
  width: 2.5rem;
  text-align: right;
  color: var(--gc-gutter);
  font-family: var(--gc-mono);
  font-size: 0.7rem;
  padding-right: 0.35rem;
}

.data-table tbody tr:hover {
  background: var(--gc-surface-alt);
}

.data-table tbody tr[data-incomplete="true"] td,
.data-table tbody tr.is-incomplete td {
  background: color-mix(in srgb, var(--gc-down) 10%, var(--gc-surface));
}

.data-table tbody tr:last-child td {
  border-bottom: 0;
}

.data-table tbody td:first-child {
  font-weight: 600;
  color: var(--gc-heading);
}

.data-table tbody td:first-child a {
  font-weight: 600;
}

/* perf: keep the heavy result tables cheap to paint */
.diff-section .data-table tbody tr,
#run-table tbody tr {
  content-visibility: auto;
  contain-intrinsic-size: 1.9rem;
}

.data-table tbody td.num,
.data-table td.num {
  font-family: var(--gc-mono);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.data-table td.mono,
.mono {
  font-family: var(--gc-mono);
  font-size: 0.86em;
  font-variant-numeric: tabular-nums;
}

/* ── Ledger list grammar (unified) ────────────────────────────── */

.repo-name {
  display: block;
  font-weight: 600;
  color: var(--gc-heading);
  line-height: 1.35;
  white-space: normal;
}

.repo-name a {
  color: inherit;
}

.repo-sub {
  display: block;
  color: var(--gc-muted);
  font-size: 0.82rem;
  margin-top: 2px;
  white-space: nowrap;
  font-family: var(--gc-mono);
}

.ledger-foot {
  margin: 0.9rem 0 0;
  padding-top: 0.6rem;
  border-top: 1px solid var(--gc-border);
  color: var(--gc-muted);
  font-size: 0.78rem;
}

.geo {
  display: inline-block;
  font-family: var(--gc-mono);
  font-size: 0.78rem;
  font-weight: 600;
  padding: 0.1rem 0.45rem;
  border: 1px solid var(--gc-border-strong);
  border-radius: 999px;
  color: var(--gc-heading);
  line-height: 1.5;
}

.geo-conf {
  display: inline-block;
  font-family: var(--gc-mono);
  font-size: 0.72rem;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  background: var(--gc-surface-alt);
  color: var(--gc-muted);
  border: 1px solid var(--gc-border);
  line-height: 1.5;
}

.data-table tr.tombstone td {
  background: var(--gc-down-bg);
}

.badge.flag.dockerfile {
  background: transparent;
  color: var(--gc-accent);
  border: 1px solid var(--gc-accent);
  text-transform: lowercase;
}

.badge.flag.tombstone {
  background: var(--gc-down-bg);
  color: var(--gc-down);
  border: 1px solid var(--gc-down);
  text-transform: lowercase;
}

/* ── Empty / error states ───────────────────────────────────────── */

.empty-state {
  text-align: center;
  padding: 2rem 1rem;
  border: 1px dashed var(--gc-border-strong);
  border-radius: var(--gc-radius);
  color: var(--gc-muted);
  background: var(--gc-surface-alt);
}

.empty-state p {
  margin: 0.2rem 0;
}

.empty-state p:first-child {
  color: var(--gc-heading);
  font-weight: 600;
}

.empty-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  justify-content: center;
  margin-top: 0.75rem;
}

.error-state {
  border-color: color-mix(in srgb, var(--gc-down) 45%, var(--gc-border));
  background: var(--gc-down-bg);
  color: var(--gc-down);
}

.error-state p:first-child {
  color: var(--gc-down);
}

.muted {
  color: var(--gc-muted);
}

/* ── Progress ───────────────────────────────────────────────────── */

.progress {
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: var(--gc-surface-alt);
  border: 1px solid var(--gc-border);
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  background: var(--gc-accent);
  width: 100%;
  transform-origin: left center;
  transform: scaleX(var(--progress, 0));
  transition: transform 0.2s ease;
}

/* ── Toast / nav progress ───────────────────────────────────────── */

.toast {
  position: fixed;
  right: 1rem;
  bottom: 2.75rem;
  max-width: 380px;
  padding: 0.65rem 0.9rem;
  border-radius: var(--gc-radius);
  background: var(--gc-surface);
  color: var(--gc-text);
  border: 1px solid var(--gc-border-strong);
  box-shadow: var(--gc-shadow-modal);
  z-index: 30;
}

.toast .button {
  margin-left: 0.35rem;
}

.nav-progress {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  z-index: 50;
  background: var(--gc-accent);
  opacity: 0.8;
}

html[data-busy="true"] .nav-progress {
  display: block;
  animation: gc-busy-pulse 1s ease-in-out infinite;
}

@keyframes gc-busy-pulse {
  50% {
    opacity: 0.25;
  }
}

a.htmx-request,
.button.htmx-request {
  cursor: progress;
  opacity: 0.7;
}

.htmx-indicator {
  display: none;
}

.htmx-request .htmx-indicator,
.htmx-request.htmx-indicator {
  display: inline;
}

/* ── Filter form ────────────────────────────────────────────────── */

.filter-form {
  display: grid;
  grid-template-columns: 320px minmax(0, 1fr);
  gap: 1.5rem;
  align-items: start;
}

.filter-form > aside {
  grid-column: 1;
  grid-row: 1 / span 3;
  position: sticky;
  top: calc(3.25rem + 1rem);
}

.filter-form > section,
.filter-form > details {
  grid-column: 2;
  min-width: 0;
}

.filter-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
}

.recent-filters {
  margin: 0 0 0.75rem;
  padding: 0.6rem 0.75rem;
  border: 1px dashed var(--gc-border);
  border-radius: var(--gc-radius);
}

.recent-filters ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0.35rem 0 0;
  padding: 0;
}

.filter-section {
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  padding: 1.25rem 1.25rem 1.35rem;
  background: var(--gc-surface);
  box-shadow: var(--gc-shadow);
}

.filter-section + .filter-section {
  margin-top: 1.25rem;
}

.filter-section h2 {
  margin: 1.2rem 0 0.7rem;
  color: var(--gc-heading);
  font-size: 0.95rem;
  font-weight: 650;
  letter-spacing: 0.01em;
}

.filter-section h2:first-child {
  margin-top: 0;
}

.filter-section > .muted:first-of-type {
  margin: 0 0 1rem;
}

.filter-section .muted {
  font-size: 0.85rem;
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
}

#detect-new .field-grid {
  grid-template-columns: minmax(0, 26rem);
}

#detect-new .form-actions {
  margin-top: 1.1rem;
}

.field-pair {
  grid-column: span 2;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.8rem 1rem;
  align-items: start;
  min-width: 0;
}

.field,
.count-row {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
}

.field-label {
  color: var(--gc-muted);
  font-weight: 600;
}

.field-input {
  width: 100%;
}

.field-note {
  font-size: 0.78rem;
}

.advanced-filters {
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  padding: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  background: transparent;
}

.advanced-filters > summary,
.filter-section > summary {
  padding: 0.6rem 1rem;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.86rem;
  color: var(--gc-heading);
  border-radius: var(--gc-radius);
}

.advanced-filters > summary:hover,
.filter-section > summary:hover {
  background: var(--gc-surface-alt);
}

.advanced-filters[open] > summary,
.filter-section[open] > summary {
  border-bottom: 1px solid var(--gc-border);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.filter-row .field {
  flex: 1 1 180px;
}

.filter-row .field-input {
  min-width: 120px;
}

.field-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin: 0.75rem 0 0;
  padding: 0.6rem 0.8rem;
  border: 1px dashed var(--gc-border);
  border-radius: var(--gc-radius);
}

.field-group[disabled] {
  opacity: 0.55;
}

.checkbox {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.count-row {
  flex-direction: column;
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  padding: 0.5rem 0.6rem;
  background: var(--gc-surface);
}

.count-row legend,
.count-row .field-label {
  flex: 1 1 100%;
}

.count-row .field-input {
  width: 100%;
}

.count-row .field-input[hidden] {
  display: none;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.form-actions form {
  margin: 0;
}

/* summary rail on the New search page */
.summary-rail-block {
  padding: 1.1rem 1.1rem;
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  margin: 0 0 1.25rem;
  background: var(--gc-surface-alt);
}

.summary-rail-block .field-label {
  display: block;
  margin-bottom: 0.35rem;
}

.action-row {
  margin-bottom: 0.9rem;
}

.action-row:last-child {
  margin-bottom: 0;
}

.action-row > p {
  margin: 0.35rem 0 0;
  font-size: 0.82rem;
  color: var(--gc-muted);
  line-height: 1.45;
}

.summary-rail-block .field {
  margin-bottom: 0.5rem;
}

.spec-sentence {
  font-family: var(--gc-mono);
  font-size: 0.86rem;
  margin: 0.25rem 0 0;
  color: var(--gc-heading);
  white-space: normal;
}

.match-count {
  font-size: 1rem;
  margin: 0.25rem 0;
  color: var(--gc-heading);
  font-family: var(--gc-mono);
}

/* per-page selector on the results page */
.per-page-form {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.per-page-form .field {
  flex-direction: row;
  align-items: center;
  gap: 0.5rem;
}

.per-page-form .field-label {
  margin: 0;
  white-space: nowrap;
}

/* ── Run detail ─────────────────────────────────────────────────── */

.run-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 1.25rem;
  color: var(--gc-muted);
  font-family: var(--gc-mono);
  font-size: 0.82rem;
}

.run-hash-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

#run-hash {
  border: 1px solid var(--gc-border-strong);
  border-radius: 5px;
  padding: 0.2rem 0.5rem;
  background: var(--gc-surface);
}

.run-status-line {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 0.35rem;
}

.run-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem 1.25rem;
  margin-top: 0.5rem;
  color: var(--gc-muted);
  font-size: 0.85rem;
}

.run-counts .count strong,
.count-value strong {
  color: var(--gc-heading);
  font-family: var(--gc-mono);
  font-variant-numeric: tabular-nums;
}

.run-counts .count {
  white-space: nowrap;
}

.count-explain {
  display: block;
  font-size: 0.78rem;
}

.count-value {
  display: inline-flex;
  align-items: baseline;
  gap: 0.35rem;
  border: 1px solid var(--gc-border-strong);
  border-radius: 999px;
  padding: 0.12rem 0.6rem;
  background: var(--gc-surface);
  color: var(--gc-muted);
}

.flags {
  margin-top: 0.75rem;
}

.flags ul,
.warnings {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.flag,
.warnings li {
  padding: 0.35rem 0.6rem;
  border-radius: 4px;
  background: color-mix(in srgb, var(--gc-warn) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--gc-warn) 55%, transparent);
  color: var(--gc-warn);
  font-size: 0.85rem;
}

.flag.error {
  background: color-mix(in srgb, var(--gc-down) 8%, transparent);
  border-color: color-mix(in srgb, var(--gc-down) 55%, transparent);
  color: var(--gc-down);
}

.flag.incomplete,
.flag.truncation,
.flag.r44 {
  background: color-mix(in srgb, var(--gc-warn) 8%, transparent);
  border-color: color-mix(in srgb, var(--gc-warn) 55%, transparent);
  color: var(--gc-warn);
}

.flags-cell .badge {
  margin-right: 0.25rem;
}

.sort-link {
  color: inherit;
  font: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
}

.sort-link:hover {
  color: var(--gc-heading);
  text-decoration: none;
}

.sort-link.active {
  color: var(--gc-accent);
}

.sort-mark {
  font-size: 11px;
  border: 1px solid var(--gc-border-strong);
  border-radius: 5px;
  padding: 0 5px;
  line-height: 1.6;
  color: var(--gc-muted);
  margin-left: 0.35rem;
  font-family: var(--gc-mono);
  vertical-align: middle;
}

.sort-link.active .sort-mark {
  color: var(--gc-accent);
  border-color: var(--gc-accent);
}

.confidence {
  color: var(--gc-muted);
  font-size: 0.8em;
}

.pagination {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.75rem;
}

/* ── Modals & dialogs ───────────────────────────────────────────── */

.modal[hidden] {
  display: none;
}

.modal {
  position: fixed;
  inset: 0;
  background: color-mix(in srgb, var(--gc-heading) 45%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 40;
}

.modal-panel {
  background: var(--gc-surface);
  border: 1px solid var(--gc-border-strong);
  border-radius: var(--gc-radius);
  box-shadow: var(--gc-shadow-modal);
  padding: 1rem 1.25rem 1.25rem;
  width: min(520px, 100%);
}

.clone-limit-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.clone-limit-row label {
  flex: 1 1 100%;
  color: var(--gc-muted);
  font-weight: 600;
}

.clone-limit-row input[type="range"] {
  flex: 1 1 220px;
  padding: 0;
  accent-color: var(--gc-accent);
}

.clone-limit-row input[type="number"] {
  width: 5.5rem;
}

.clone-modes {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 1rem;
  border: 1px dashed var(--gc-border);
  border-radius: var(--gc-radius);
  padding: 0.55rem 0.75rem;
  margin: 0 0 0.75rem;
}

.clone-modes legend {
  color: var(--gc-muted);
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  padding: 0 0.25rem;
}

.clone-modes label {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.clone-estimate {
  margin-bottom: 0.75rem;
}

.clone-estimate p {
  margin: 0.2rem 0;
}

.clone-cancel-row {
  margin: 0.5rem 0 0;
}

.row-selected {
  background: var(--gc-selected) !important;
  outline: 2px solid var(--gc-accent);
  outline-offset: -2px;
}

.run-filters,
.diff-baseline-form {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
  margin-bottom: 0.9rem;
  border: 1px solid var(--gc-border);
  border-radius: 6px;
  padding: 0.9rem 1rem;
  background: var(--gc-surface);
}

.run-filters .field,
.diff-baseline-form .field {
  flex: 1 1 220px;
}

.inline-form {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0;
}

.inline-input {
  width: 9rem;
}

.inline-details {
  position: relative;
  display: inline-block;
}

.inline-details > summary {
  list-style: none;
  display: inline-flex;
  cursor: pointer;
}

.inline-details > summary::-webkit-details-marker {
  display: none;
}

.inline-details[open] > summary {
  background: var(--gc-surface-alt);
}

.inline-details .inline-form {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.3rem);
  left: 0;
  background: var(--gc-surface);
  border: 1px solid var(--gc-border-strong);
  border-radius: var(--gc-radius);
  box-shadow: var(--gc-shadow-modal);
  padding: 0.5rem;
}

.actions-row {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.4rem;
  white-space: nowrap;
}

.actions-row .button {
  padding: 0.22rem 0.6rem;
  font-size: 0.78rem;
}

.actions-row .button.ghost {
  background: var(--gc-surface);
  border-color: var(--gc-border-strong);
  color: var(--gc-heading);
}

/* the cell must stay a table-cell: flex on a <td> breaks border-collapse */
.data-table td.actions-cell {
  text-align: right;
  white-space: nowrap;
}

.library-name {
  font-weight: 650;
  color: var(--gc-heading);
}

.data-table td.library-sentence {
  color: var(--gc-text);
  max-width: 36rem;
  white-space: normal;
}

.library-last-used {
  color: var(--gc-muted);
}

#corpora-table td.library-sentence {
  max-width: 20rem;
}

/* ── Summary & diff ─────────────────────────────────────────────── */

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.diff-card {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.diff-card strong {
  font-size: 1.6rem;
  font-family: var(--gc-mono);
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}

.diff-label {
  color: var(--gc-muted);
}

.diff-section {
  margin-bottom: 1rem;
}

.diff-from {
  color: var(--gc-down);
  font-family: var(--gc-mono);
  font-size: 0.86em;
}

.diff-to {
  color: var(--gc-ok);
  font-family: var(--gc-mono);
  font-size: 0.86em;
}

.diff-direction {
  margin: 0.6rem 0 0;
}

kbd {
  background: var(--gc-surface-alt);
  border: 1px solid var(--gc-border-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  padding: 0.1rem 0.4rem;
  font-family: var(--gc-mono);
  font-size: 0.82em;
}

/* ── Status dot ─────────────────────────────────────────────────── */

.dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  vertical-align: middle;
}

.dot-green {
  background: var(--gc-ok);
  box-shadow: 0 0 4px color-mix(in srgb, var(--gc-ok) 60%, transparent);
}

.dot-amber {
  background: var(--gc-warn);
  box-shadow: 0 0 4px color-mix(in srgb, var(--gc-warn) 60%, transparent);
}

.dot-red {
  background: var(--gc-down);
  box-shadow: 0 0 4px color-mix(in srgb, var(--gc-down) 60%, transparent);
}

/* ── Quality panel ─────────────────────────────────────────────── */

.quality-checks {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.quality-checks li {
  padding: 0.5rem 0.15rem;
  border-bottom: 1px solid var(--gc-border);
  border-radius: 0;
  font-size: 0.88rem;
  background: transparent;
}

.quality-checks li:last-child {
  border-bottom: 0;
}

.quality-checks li strong {
  color: var(--gc-heading);
}

.quality-checks .check-ok {
  color: var(--gc-ok);
}

.quality-checks .check-warn {
  color: var(--gc-warn);
}

.quality-checks .check-fail {
  color: var(--gc-down);
}

.quality-checks li .muted {
  color: inherit;
  opacity: 0.85;
}

/* ── Settings page bits ────────────────────────────────────────── */

.banner {
  padding: 0.5rem 0.75rem;
  border-radius: 4px;
  background: var(--gc-ok-bg);
  color: var(--gc-ok);
  font-size: 0.88rem;
}

.errors,
.hints {
  margin: 0.75rem 0;
  padding-left: 1.25rem;
  font-size: 0.88rem;
}

.errors {
  color: var(--gc-down);
}

.hints {
  color: var(--gc-muted);
}

/* ── Metrics cards partial ─────────────────────────────────────── */

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 0.75rem;
}

.cards .card h3 {
  margin: 0 0 0.25rem;
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--gc-muted);
}

.cards .card p {
  margin: 0;
  font-family: var(--gc-mono);
  font-size: 1.15rem;
  color: var(--gc-heading);
  font-variant-numeric: tabular-nums;
}

.limiter {
  color: var(--gc-muted);
  font-size: 0.82rem;
}

/* ── Misc helpers ──────────────────────────────────────────────── */

.country {
  font-family: var(--gc-mono);
  font-variant-numeric: tabular-nums;
}

.shortcuts-table td {
  white-space: normal;
}

/* ── Small screens ─────────────────────────────────────────────── */

@media (max-width: 760px) {
  .site-header {
    flex-wrap: wrap;
    height: auto;
    padding: 0.5rem 1rem;
    gap: 0.5rem 0.75rem;
  }

  .health-grid {
    grid-template-columns: 1fr;
  }

  .content {
    padding: 1rem 1rem 2rem;
  }

  .filter-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .filter-form > aside {
    grid-column: 1;
    grid-row: auto;
    position: static;
  }

  .filter-form > section,
  .filter-form > details {
    grid-column: 1;
  }

  .summary-rail-block:last-child {
    margin-bottom: 0;
  }

  .inline-details .inline-form {
    position: static;
    box-shadow: none;
    border: 0;
  }
}

/* motion: respect the OS setting */
@media (prefers-reduced-motion: reduce) {
  .nav-progress,
  .progress-bar,
  .button,
  input,
  select {
    transition: none;
    animation: none;
  }

  html[data-busy="true"] .nav-progress {
    animation: none;
  }
}


/* Live run progress */
#run-clock-line {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.progress-track {
  background-image: linear-gradient(
    90deg,
    color-mix(in srgb, var(--gc-border-strong) 45%, transparent) 0 2px,
    transparent 2px 4px
  );
  background-size: 4px 100%;
  border: 1px solid var(--gc-border-strong);
  border-radius: 4px;
  display: inline-block;
  height: 10px;
  overflow: hidden;
  vertical-align: middle;
  width: 100%;
  max-width: 28rem;
}
.progress-fill {
  background-image: linear-gradient(90deg, var(--gc-accent) 0 2px, transparent 2px 4px);
  background-size: 4px 100%;
  border-radius: 0;
  display: block;
  height: 100%;
  transition: width 0.4s ease;
}
#abort-run {
  margin-top: 0.75rem;
}
#detect-status .inline-form {
  margin-top: 0.75rem;
}
#run-timestamps {
  margin-top: 0.75rem;
}
/* Per-repo evidence blocks (detection pages) */
#detection-filters {
  margin-bottom: 0.75rem;
}
.evidence-repo {
  background: var(--gc-surface);
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  margin-bottom: 0.5rem;
}
.evidence-repo > summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1rem;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.86rem;
  color: var(--gc-heading);
  border-radius: var(--gc-radius);
}
.evidence-repo > summary:hover {
  background: var(--gc-surface-alt);
}
.evidence-repo[open] > summary {
  border-bottom: 1px solid var(--gc-border);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}
.evidence-repo .evidence-body {
  padding: 0.35rem 1rem 0.75rem;
  max-height: 24rem;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--gc-border-strong) transparent;
}
.evidence-repo h4 {
  margin: 0.6rem 0 0.3rem;
  font-size: 0.72rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--gc-muted);
}
.evidence-repo ul {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin: 0;
  padding-left: 1.1rem;
  font-size: 0.88rem;
}
/* Info popovers on the detection summary cards */
#detection-summary .card {
  position: relative;
}
#detection-summary .card h3 {
  padding-right: 1.4rem;
}
.info-pop {
  letter-spacing: normal;
  position: absolute;
  right: 0.5rem;
  text-transform: none;
  top: 0.45rem;
}
.info-pop > summary {
  align-items: center;
  border: 1px solid var(--gc-border-strong);
  border-radius: 999px;
  color: var(--gc-muted);
  cursor: pointer;
  display: flex;
  font-family: var(--gc-mono);
  font-size: 0.68rem;
  font-weight: 700;
  height: 1.05rem;
  justify-content: center;
  list-style: none;
  width: 1.05rem;
}
.info-pop > summary::-webkit-details-marker {
  display: none;
}
.info-pop > summary:hover,
.info-pop[open] > summary {
  background: var(--gc-surface-alt);
  color: var(--gc-heading);
}
.info-pop-body {
  background: var(--gc-surface);
  border: 1px solid var(--gc-border-strong);
  border-radius: var(--gc-radius);
  box-shadow: var(--gc-shadow-modal);
  font-size: 0.82rem;
  font-weight: 400;
  letter-spacing: normal;
  padding: 0.7rem 0.85rem;
  position: absolute;
  right: 0;
  text-transform: none;
  top: calc(100% + 0.35rem);
  width: min(22rem, 78vw);
  z-index: 30;
}
#detection-summary .info-pop-body p {
  font-family: inherit;
  font-size: 0.82rem;
  line-height: 1.5;
  margin: 0 0 0.45rem;
}
#detection-summary .info-pop-body p:last-child {
  margin-bottom: 0;
}
/* Detection options page */
.detect-section-head {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  justify-content: space-between;
}
.detect-section-head h2 {
  margin: 0;
}
.checklist-tools {
  align-items: center;
  display: flex;
  flex-wrap: nowrap;
  gap: 0.5rem;
}
.checklist-search {
  flex: 0 0 16rem;
  max-width: 16rem;
  min-width: 10rem;
}
.checklist {
  background: var(--gc-surface);
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  display: grid;
  gap: 0.35rem 1rem;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  margin-top: 0.6rem;
  max-height: 17rem;
  overflow-y: auto;
  padding: 0.6rem 0.75rem;
  scrollbar-color: var(--gc-border-strong) transparent;
  scrollbar-width: thin;
}
.checklist .checkbox:not(.channel-row) {
  white-space: nowrap;
}
.checklist .checkbox[hidden] {
  display: none;
}
.checklist-channels {
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  max-height: none;
}
.channel-row {
  align-items: baseline;
  display: grid;
  gap: 0.1rem 0.5rem;
  grid-template-columns: auto 1fr;
  white-space: normal;
}
.channel-row .channel-name {
  font-weight: 600;
}
.channel-row .channel-note {
  font-size: 0.78rem;
  grid-column: 2;
}
#detect-pack-section .field,
#detect-scope-section .field {
  max-width: 24rem;
}
#detect-estimate {
  background: var(--gc-surface);
  border: 1px solid var(--gc-border);
  border-radius: var(--gc-radius);
  margin-top: 0.85rem;
  padding: 0.7rem 0.9rem;
}
#detect-estimate p {
  margin: 0;
}
#detect-estimate p + p {
  margin-top: 0.45rem;
}
#detect-estimate strong {
  color: var(--gc-heading);
  font-family: var(--gc-mono);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 640px) {
  .checklist-tools {
    flex-wrap: wrap;
    width: 100%;
  }
  .checklist-search {
    flex: 1 1 100%;
    max-width: none;
  }
}

/* ── Console chrome (v3) ───────────────────────────────────────── */

.status-bar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 15;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem 1.25rem;
  padding: 0.32rem 1.25rem;
  background: var(--gc-surface);
  border-top: 1px solid var(--gc-border);
  font-family: var(--gc-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--gc-muted);
  flex-wrap: wrap;
}

.status-bar .status-left,
.status-bar .status-right {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem 0.75rem;
  flex-wrap: wrap;
}

.status-bar .dot {
  width: 7px;
  height: 7px;
}

.status-bar .st-ok {
  color: var(--gc-ok);
}

.status-bar .st-warn {
  color: var(--gc-warn);
}

.status-bar .st-down {
  color: var(--gc-down);
}

.status-bar .sep {
  color: var(--gc-border-strong);
}

.status-bar a {
  color: var(--gc-muted);
}

.status-bar a:hover {
  color: var(--gc-heading);
}

.status-bar .status-label {
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.points-card {
  flex-direction: column;
  align-items: stretch;
  gap: 0.5rem;
}

.points-meter {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.points-card .progress-track {
  max-width: none;
  flex: 1 1 auto;
}

.points-value {
  white-space: nowrap;
  color: var(--gc-heading);
}

.prompt-field {
  position: relative;
}

.prompt-field .prompt-glyph {
  position: absolute;
  left: 0.6rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gc-accent);
  pointer-events: none;
  font-size: 0.82rem;
}

.prompt-field .field-input {
  padding-left: 1.65rem;
  font-family: var(--gc-mono);
  font-size: 0.86rem;
}

.action-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr));
  gap: 0.5rem;
  align-items: stretch;
}

.action-grid > .button,
.action-grid > form > .button {
  margin: 0;
  width: 100%;
}

.action-grid > form {
  display: flex;
  margin: 0;
}

.action-grid #compare-form {
  grid-column: 1 / -1;
}

.action-grid #compare-form .field {
  flex: 1 1 auto;
}

@media (max-width: 640px) {
  .status-bar .status-mid {
    display: none;
  }
}
